def clean(t):
 t=t.replace('J. et al. 2002','Jansa et al. 2002').replace('q0.25','q ≤ 0.25').replace('q0.05','q ≤ 0.05').replace('p0.997','p ≥ 0.997').replace('p\\<0.05','p < 0.05').replace('R2','R²').replace('stronger Inference','stronger inference')
 t=t.replace('integrated','cross-marker').replace('Integration across marker datasets','Cross-marker integration').replace('Joint','Cross-marker')
 t=t.replace('AMF marker datasets','18S (AMF) datasets').replace('16S, ITS, and AMF marker datasets','16S, ITS, and 18S (AMF) datasets')
 t=t.replace('Figure 8','Figure S31').replace('Figure 7','Figure 8').replace('Figure 6','Figure 7').replace('Figure 5','Figure 6').replace('Figure 4','Figure 5').replace('Figure 3','Figure 2D')
 return t
repl={}
repl[14]='''Microbial associations with agricultural management can differ among diversity, composition, individual taxa, and inferred networks. We analyzed fresh-frozen soybean-field soils from operational farms in Ohio using 16S rRNA, ITS, and AMF-targeted 18S rRNA amplicons. The datasets contained 44, 43, and 44 observations, respectively, with approximately three times as many no-till (NT) as vertical-tillage (till) observations. Richness and Shannon diversity did not differ detectably between management groups. Unadjusted management-only PERMANOVA detected associations for 16S and ITS (R² = 0.047 and 0.065; both p = 0.006), but not 18S (R² = 0.031; p = 0.072). Date-inclusive distance-based redundancy analysis (dbRDA), incorporating management, sampling date, site code, and depth, explained 14.0%, 13.1%, and 9.1% of adjusted community variation. Management was completely aliased with one sampling date; its unique effect therefore could not be estimated. Descriptive variance partitioning assigned 6.8%, 2.9%, and 4.4% to date conditional on the other predictor sets, without establishing temporal causation. The retained samples were collected over ten days in late autumn, not across seasons. In 20 balanced subsets, the management-only community association met p < 0.05 in 18, 7, and 4 iterations for 16S, ITS, and 18S, whereas feature-level detection followed a different ranking. The large unbalanced AMF network contrast contracted substantially after balancing. Carbon associations remain provisional because the models omit design covariates and matched AMF chemistry records disagree. These results describe management-associated patterns whose interpretation depends on the analytical summary, sample balance, and confounding with collection date and site.'''
repl[17]=clean(p[17]).replace('Here we use the MF metadata subset','Here we use the fresh-frozen soybean-soil subset')+' We additionally use date-inclusive dbRDA and variance partitioning to assess which components of the observed variation can be distinguished within the available sampling design.'
repl[20]=p[20]+' These details describe the broader collection; the retained analytical cohort is narrower.'
repl[21]='''The present analysis compared no-till (NT) and vertical-tillage (till) soybean soils. Matching retained sample identifiers to the control workbook identified four collection dates (21, 22, and 28 November and 1 December 2022) and two depths (0–10 and 10–30 cm). The 30–60 cm interval and later collection trips in the broader study are not represented in these analytical cohorts. Each marker included observations from 24 workbook profile identifiers, with one or two retained depths per profile. All till observations were collected on 28 November; no NT observations were collected on that date. The two-level site code was retained as a design covariate and is not a substitute for the full farm hierarchy.'''
# Split the mixed methods paragraph at build time.
repl[23]=clean(p[23]).replace('2.2 DNA extraction, marker-gene amplification, and sequencing ','').replace('Sequence data were deposited in the National Center for Biotechnology Information (NCBI) under BioProject accession PRJNA1371968. ','').replace('2.3 Sequence processing and construction of microbial community datasets','\nSPLIT_SEQUENCE\n').replace('according to soil depth as 0–10, 10–30, or 30–60 cm','according to the two retained soil depths, 0–10 and 10–30 cm').replace('The resulting three datasets are referred to throughout the study as the 16S, ITS, and AMF marker datasets.','The datasets are labeled 16S, ITS, and 18S (AMF); AMF denotes the biological target of the 18S assay.').replace('the 16S, ITS, and AMF marker datasets','the 16S, ITS, and 18S (AMF) datasets')
repl[25]=clean(p[25]).replace('The six alpha-diversity tests are reported with their original, unadjusted p values; none met 0.05.','We report raw p values and Benjamini–Hochberg (BH) q values across the six alpha-diversity comparisons; none met 0.05 under either criterion.')+' For the revised unconstrained displays, PCoA used Bray–Curtis distances with a Lingoes correction where required to remove negative eigenvalues. The saved management-only PERMANOVA statistics use uncorrected Bray–Curtis distances; they are not recomputed from the two plotted axes. PCoA percentages use total corrected inertia. No group ellipses are shown, avoiding confusion between sample dispersion and confidence intervals for centroids.'
repl[27]='''Cross-marker integration retained 42 shared samples (33 NT, 9 till). Within each marker, features with at least 5% prevalence were retained and capped at the 200 most abundant features. One was added to each count before a centered log-ratio (CLR) transformation within each marker. The marker-specific matrices were concatenated and standardized feature by feature before PCA; PERMANOVA used Euclidean distances on that same standardized matrix. PCA is used here as a descriptive projection of transformed log-ratios rather than of raw counts (Gloor et al. 2017). Feature standardization changes the usual Aitchison geometry and weights low- and high-variance features equally. Consequently, this is standardized CLR-PCA, not robust Aitchison PCA (Martino et al. 2019). Equal feature caps do not ensure equal marker contributions, and ITS and AMF-targeted 18S can represent overlapping fungal information. Figure 2D combines this display with the three marker-specific PCoAs.'''
repl[31]=clean(p[31]).replace('Edges required 0.6','Edges required Spearman |ρ| ≥ 0.6')+' A single graph was fitted for each marker–management combination; candidate features can differ between groups. These descriptive graph summaries therefore have no between-field standard errors.'
repl[32]='Secondary carbon models'
repl[35]=clean(p[35]).replace('No new biological hypotheses were tested during manuscript assembly.','The revision additionally incorporated the date-inclusive models described above.').replace('The original R scripts and the manuscript-building scripts are included with the package.','The R analysis scripts remain in the parent manuscript package; the revision includes Python analysis and figure-building scripts.')
repl[38]=clean(p[38]).replace('44 samples and 33,112 retained features for 16S, 43 samples and 162 features for ITS, and 44 samples and 3,142 features for AMF','44 samples and 9,526 observed ASVs for 16S, 43 samples and 155 observed ASVs for ITS, and 44 samples and 790 observed ASVs for 18S (AMF)').replace('Median library totals differed between assays and treatments, reinforcing the need to interpret the richness values within each assay.','Pooled median retained count totals are reported by marker in Table 1. These are totals in the supplied processed ASV matrices, not pre-QC sequencing yields.').replace('All subsequent results refer to the original supplied analyses, with this qualification.','The new date-inclusive analyses use workbook dates and depths aligned by sample identifier. The older management-only and carbon outputs retain their original metadata; their limitations remain explicit.')
repl[40]=clean(p[40]).replace('5.146 versus 5.122, 2.668 versus 2.632, and 2.723 versus 2.930','5.15 versus 5.12, 2.67 versus 2.63, and 2.72 versus 2.93').replace('p=0.0626 to p=0.698','p = 0.063 to p = 0.698')+' BH adjustment across the six comparisons did not change this conclusion (Table 2).'
repl[41]='Management-only community comparisons'
repl[42]='''The saved management-only PERMANOVA attributed 4.7% of Bray–Curtis variation to the management grouping for 16S (pseudo-F = 2.07, p = 0.006), 6.5% for ITS (pseudo-F = 2.86, p = 0.006), and 3.1% for 18S (pseudo-F = 1.36, p = 0.072; Figure 2A–C; Table 3). These unadjusted group comparisons do not isolate tillage from collection date, site, or depth. Cross-marker PERMANOVA on standardized CLR features gave R² = 0.051, pseudo-F = 2.15, and p = 0.004 (Figure 2D). The cross-marker association does not establish independent responses by each assay. Management-group PERMDISP p values were 0.565, 0.481, and 0.074 for 16S, ITS, and 18S. These diagnostics did not detect differences at 0.05, but do not establish equal dispersion or independent field replication. The revised PCoAs display all three markers; archived NMDS plots remain in the existing supplementary atlas.'''
repl[53]=clean(p[53]).replace('the site imbalance','confounding with site and date')
repl[59]=clean(p[59]).replace('The most consequential current limitation is the incomplete separation of site from management.','The most consequential limitation is complete management–date aliasing, accompanied by partial site–management confounding.').replace('Restricted permutations, block-aware models, and carefully chosen within-site contrasts should be considered after the experimental unit and sampling structure are confirmed.','The added dbRDA uses profile-preserving permutations, but broader field dependence is not controlled and unique management effects remain non-identifiable after accounting for date. Future within-site comparisons must also overlap in collection date and verify the experimental unit.')
repl[61]=clean(p[61])+' The date-inclusive analysis further shows that apparent management separation cannot be assigned uniquely to tillage: management adds no information after the date indicators. Date, site, and depth together account for modest adjusted fractions, leaving most compositional variation unexplained.'
repl[62]=clean(p[62]).replace('Site–management confounding','Management–date aliasing, site–management confounding')
repl[64]='''The existing supplementary atlas, supplementary_tables.xlsx, and supplementary_data directory preserve the earlier analysis outputs. This revision adds corrected figures, date-inclusive model tables, a per-sample manifest with retained read totals, and reproducible revision scripts in the draft3 directory. The supplied phyloseq RDS objects remain in the parent workspace. Draft 2 identifies BioProject PRJNA1371968; its public accessibility and association with these samples could not be verified during this revision. Pre-QC read counts, complete sequencing-processing settings, source chemistry methods and units, and a public code/data repository remain to be supplied or confirmed. Retained matrix totals must not be substituted for unavailable raw-read or processing-stage counts.'''
method_title='Date-inclusive dbRDA and variance partitioning'
method_text='''We fitted community ~ management + sampling date + site code + depth separately for each marker, treating all four predictor sets as categorical. Relative-abundance Bray–Curtis distances were Lingoes-corrected, and all positive principal coordinates were projected onto the centered model matrix using singular-value decomposition (Legendre and Anderson 1999). The model had five effective predictor degrees of freedom: the till indicator was identical to the 28 November date indicator. Plotted site scores are projections of observed communities onto constrained directions; axis percentages refer to total corrected inertia. The implementation uses NumPy/SciPy linear algebra, not an R/vegan fit. Distance reconstruction, projection identities, model rank, sample identities, and partition reconstruction were checked, and the complete saved analysis was rerun for this revision.'''
method_text2='''Full-model pseudo-F tests used 9,999 permutations. Workbook profiles were exchanged only among profiles with identical observed depth coverage, and observations could also be exchanged within each profile. This preserves profile membership while permitting a joint test that includes depth. It assumes exchangeability among profiles within coverage strata and of depths under the full null; broader field clustering is not controlled. These are exploratory omnibus tests, not tests of unique management or seasonal effects. BH adjustment was applied across the three full-model tests. Sampling-date-only diagnostics are reported separately in the supplementary addendum.'''
method_text3='''Variance partitioning used all 15 nonempty combinations of the four predictor sets. For each fit, adjusted R² = 1 − (1 − R²)(n − 1)/(n − k − 1), where k is the effective rank of the centered predictor matrix (Peres-Neto et al. 2006). Each unique fraction equals full-model adjusted R² minus the corresponding model excluding that set. The combined shared fraction is full-model adjusted R² minus the sum of unique fractions; unexplained variation is 1 minus full-model adjusted R². Negative adjusted fractions were retained in the complete outputs. Fractions are descriptive and have no individual permutation tests. Sample-level adjusted R² does not correct for profile dependence. The algebraic zero for unique management signifies non-identifiability after date, not evidence that management is unrelated to composition. Carbon is excluded from this four-set partition because chemistry discrepancies remain unresolved.'''
result_title='Date-inclusive models reveal non-identifiable management effects'
result_text='''The full dbRDA models explained 24.0%, 23.4%, and 19.7% of corrected inertia for 16S, ITS, and 18S, respectively; adjusted R² values were 0.140, 0.131, and 0.091 (Figure 3; Table 7). All exploratory omnibus tests had BH q < 0.001. This evidence concerns the combined predictor space and cannot be attributed to management alone. All till samples were collected on 28 November 2022, whereas NT samples were collected on the other three dates. Management therefore added zero degrees of freedom after date in all three datasets.'''
result_text2='''Four-set variance partitioning assigned unique date fractions of 6.8%, 2.9%, and 4.4% to 16S, ITS, and 18S, respectively, conditional on management, site code, and depth (Figure 4; Table 8). Unique site fractions were 1.5%, 1.9%, and 1.8%, and unique depth fractions were 3.4%, 4.2%, and 1.7%. Combined shared fractions were 2.3%, 4.1%, and 1.3%; unexplained fractions were 86.0%, 86.9%, and 90.9%. These fractions carry no individual significance tests. In particular, unique date variation represents contrasts remaining after management and other covariates; it is not an independently identified seasonal effect. The supplementary date-colored PCoA (Figure S54) and date-only tests (Table S13) show date-associated structure. The 16S date-group dispersion test remained significant after BH correction (q = 0.026), whereas ITS and 18S did not (q = 0.198 and 0.071), further qualifying the date-group contrasts.'''
disc_title='Collection date is part of the design, not an isolated seasonal mechanism'
disc_text='''Temporal variation provides ecological context for including date. In Michigan, monthly sampling of conventional and reduced-input row-crop soils and successional grasslands revealed temporal bacterial variation associated with soil moisture and temperature; land-use compositional differences nevertheless remained comparatively consistent over the seven-month period (Lauber et al. 2013). Such findings show why timing matters without implying that it always outweighs management. Here, the retained samples cover only ten days in late autumn 2022. They cannot quantify seasonal turnover or separate temporal change from which fields were sampled on each date. The descriptive date fractions and significant full-model tests therefore support attention to collection design, not a claim that season drove the observed communities. Sampling both management groups on shared dates, with replicated fields and matched depths, would be needed to estimate a management contrast separately from timing.'''

def setup(doc):
 sec=doc.sections[0];sec.top_margin=sec.bottom_margin=Inches(.7);sec.left_margin=sec.right_margin=Inches(.7)
 normal=doc.styles['Normal'];normal.font.name='Calibri';normal.font.size=Pt(11);normal.paragraph_format.space_after=Pt(7)
 for name in ['Heading 1','Heading 2']:
  doc.styles[name].font.name='Calibri';doc.styles[name].font.color.rgb=RGBColor.from_string('163C4A')
 foot=sec.footer.paragraphs[0];foot.alignment=WD_ALIGN_PARAGRAPH.RIGHT
 foot.add_run('Draft 3 | ');fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');foot._p.append(fld)
def para(doc,t):
 for phrase in ['Field studies illustrate','Arbuscular mycorrhizal fungi warrant','Carbon provides another','Microbial networks offer','Here we use','Treatment-associated features were not','Carbon-inclusive MaAsLin2 output','Additive Hellinger variance partitioning','Most bootstrap network','The contrast between community-level','Nondetection of alpha-diversity','The balanced AMF analysis','More generally, network architecture','The statistical design introduces','A second priority is metadata','Finally, the reported models']:
  t=t.replace(' '+phrase, '\n'+phrase)
 for s in t.split('\n'):
  if s.strip():doc.add_paragraph(s)
def table(doc,title,headers,rows,note,widths=None):
 doc.add_heading(title,2);t=doc.add_table(rows=1,cols=len(headers));t.style='Light Shading Accent 1';t.autofit=True
 for c,v in zip(t.rows[0].cells,headers):c.text=str(v)
 for row in rows:
  for c,v in zip(t.add_row().cells,row):c.text=str(v)
 for row in t.rows:
  for c in row.cells:
   for p0 in c.paragraphs:
    p0.paragraph_format.space_after=Pt(3);p0.paragraph_format.space_before=Pt(3)
    for r in p0.runs:r.font.size=Pt(9)
  trpr=row._tr.get_or_add_trPr();trpr.append(OxmlElement('w:cantSplit'))
 t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
 if widths:
  for row in t.rows:
   for c,w in zip(row.cells,widths):c.width=Inches(w)
  for c,w in zip(t.columns,widths):c.width=Inches(w)
 doc.add_paragraph(note)
 return t
def fig(doc,name,title,cap):
 doc.add_page_break();doc.add_heading(title,2);doc.add_picture(str(O/'figures'/f'{name}.png'),width=Inches(7.0));doc.add_paragraph(cap)

